const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

export interface Customer {
  yearsWithMHPCO: number;
}

export function quote(items: Item[], customer: Customer = { yearsWithMHPCO: 0 }): number {
