export interface Item {
  type: string;
  cursed?: boolean;
  enchantment?: number;
  material?: string;
}

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_TYPES = ['rune', 'moonstone'];
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

export interface Customer {
  yearsWithMHPCO: number;
}

export function quote(
  items: Item[],
  customer: Customer = { yearsWithMHPCO: 0 },
  previousContracts = 0,
): number {
  let base = 0;
  let surcharges = 0;
  for (const item of items) {
    const itemBase = BASE_PREMIUM[item.type];
    if (itemBase === undefined) {
      throw new Error(`unknown item type: ${item.type}`);
    }
    base += itemBase;
    if (item.cursed) {
      surcharges += itemBase * 0.5;
    }
    if (item.enchantment !== undefined && item.enchantment >= 5) {
      surcharges += itemBase * 0.3;
    }
  }
  for (const componentType of COMPONENT_TYPES) {
    const count = items.filter((item) => item.type === componentType).length;
    if (count === BLOCK_SIZE) {
      base -= count * BASE_PREMIUM[componentType] - BLOCK_PREMIUM;
    }
  }
  let policyModifiers = base * 0.1;
  if (customer.yearsWithMHPCO >= 2) {
    policyModifiers -= base * 0.2;
  }
  if (previousContracts > 0) {
    policyModifiers -= base * 0.15;
  }
  return Math.ceil(base + surcharges + policyModifiers + 5);
}

